package com.aistock.scheduler.task;
import java.time.*;import java.util.*;import com.aistock.common.BusinessException;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@Tag("mysql") class TaskVerificationMysqlTest {
 final TaskRepository r=new TaskMysqlTest().repo();final Instant now=Instant.now();final LocalDate due=now.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().minusDays(1);final String pred=UUID.randomUUID().toString();static final String RULE="origin-share-close-v1";
 TaskRepository.Task task(String key,Instant at){return r.createVerification(pred,"SH600030",due,RULE,key,at);}
 @Test void typedDedupConflictAndSkipCannotInventVersion(){var t=task("v-key",now);assertEquals(t.taskId(),task("v-key",now).taskId());assertEquals("PREDICTION_VERIFY",t.taskType());assertEquals(pred,t.predictionId());assertThrows(BusinessException.class,()->r.create("SH600030",due,"v-key",now));assertThrows(BusinessException.class,()->r.createVerification(UUID.randomUUID().toString(),"SH600030",due,RULE,"v-key",now));var c=r.claim(now);assertEquals(now.plusSeconds(120).toEpochMilli(),c.leaseUntil().toEpochMilli());r.finish(c,new MarketRefreshClient.Result(c.attemptId(),"SKIPPED_NOT_DUE",null,null),now.plusSeconds(1));assertEquals("SKIPPED",r.get(t.taskId()).state());assertNull(r.get(t.taskId()).versionId());assertEquals(1,r.attempts(t.taskId()).size());}
 @Test void transientRetriesButRawMismatchStops(){var t=task("errors",now);var c=r.claim(now);r.finish(c,new MarketRefreshClient.Result(c.attemptId(),"FAILED",null,"VERIFICATION_SOURCE_UNAVAILABLE"),now.plusSeconds(1));assertEquals("RETRY_WAIT",r.get(t.taskId()).state());var next=r.claim(now.plusSeconds(61));r.finish(next,new MarketRefreshClient.Result(next.attemptId(),"FAILED",null,"REALIZATION_RAW_MISMATCH"),now.plusSeconds(62));assertEquals("FAILED",r.get(t.taskId()).state());}
 @Test void lostVerificationReplyRecoversSameAttemptWithoutCallingMarket(){var t=task("lost",now);var market=mock(MarketRefreshClient.class);var receipt=mock(MarketReceiptClient.class);var prediction=mock(PredictionTaskClient.class);String version=UUID.randomUUID().toString();when(prediction.execute(any())).thenThrow(new IllegalStateException("lost"));when(prediction.receipt(any())).thenAnswer(a->{TaskRepository.Claim c=a.getArgument(0);return new MarketRefreshClient.Result(c.attemptId(),"AVAILABLE",version,null);});new TaskWorker(r,market,receipt,prediction,"t",false).runOnce();assertEquals("SUCCEEDED",r.get(t.taskId()).state());assertEquals(version,r.get(t.taskId()).versionId());assertEquals(1,r.attempts(t.taskId()).size());verifyNoInteractions(market,receipt);}
 @Test void restartUnknownOutcomeDoesNotRetryBlindly(){var t=task("unknown",now.minusSeconds(130));var old=r.claim(now.minusSeconds(130));var market=mock(MarketRefreshClient.class);var receipt=mock(MarketReceiptClient.class);var prediction=mock(PredictionTaskClient.class);when(prediction.receipt(any())).thenThrow(new IllegalStateException("down"));var worker=new TaskWorker(r,market,receipt,prediction,"t",false);worker.runOnce();assertEquals("RECONCILING",r.get(t.taskId()).state());assertEquals(1,r.attempts(t.taskId()).size());verify(prediction,never()).execute(any());doReturn(new MarketRefreshClient.Result(old.attemptId(),"AVAILABLE",UUID.randomUUID().toString(),null)).when(prediction).receipt(any());worker.runOnce();assertEquals("SUCCEEDED",r.get(t.taskId()).state());assertEquals(1,r.attempts(t.taskId()).size());verifyNoInteractions(market,receipt);}
 @Test void missingReceiptBeforeLeaseIsNotRetriedAndAfterLeaseIsConfirmedExpired(){var t=task("missing-before",now);r.claim(now);var market=mock(MarketRefreshClient.class);var receipt=mock(MarketReceiptClient.class);var prediction=mock(PredictionTaskClient.class);when(prediction.receipt(any())).thenThrow(new PredictionTaskClient.MissingReceipt());new TaskWorker(r,market,receipt,prediction,"t",false).runOnce();assertEquals("RUNNING",r.get(t.taskId()).state());assertEquals(1,r.attempts(t.taskId()).size());verify(prediction,never()).execute(any());var t2=task("missing-after",now.minusSeconds(130));r.claim(now.minusSeconds(130));new TaskWorker(r,market,receipt,prediction,"t",false).runOnce();assertEquals("RETRY_WAIT",r.get(t2.taskId()).state());assertEquals(1,r.attempts(t2.taskId()).size());verifyNoInteractions(market,receipt);}
}
